{"op":"define","frontend":"flow","syntaxVersion":2,"source":"fn invoice.queue-reminder-once(invoice: Invoice) -> String {
    effects fs.read, fs.write
    doc "Queues a reminder once for an invoice whose status is exactly open, preserving existing reminder contents."

    if invoice.status == InvoiceStatus::new("open") {
        let path = invoice::reminder-path(invoice.id);
        if file::exists?(path) {
            file::read(path)
        } else {
            file::write(path, "queued");
            "queued"
        }
    } else {
        "not-open"
    }
